import{_ as o,o as a,c as t,ag as s}from"./chunks/framework.44aEvdQQ.js";const d=JSON.parse('{"title":"Operating Values vs Core Values","description":"","frontmatter":{"title":"Operating Values vs Core Values","order":3},"headers":[],"relativePath":"about/chapters/03-operating-values-vs-core-values.md","filePath":"about/chapters/03-operating-values-vs-core-values.md"}'),r={name:"about/chapters/03-operating-values-vs-core-values.md"};function i(n,e,l,u,h,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h4 id="behaviors-not-words" tabindex="-1">Behaviors, not words <a class="header-anchor" href="#behaviors-not-words" aria-label="Permalink to &quot;Behaviors, not words&quot;">​</a></h4><p>Core values are verbs or nouns you claim are adjectives, that describe your behavior. They&#39;re worth having, worth publishing on your website, and worth instilling in your people. They&#39;re good but operating values are more useful.</p><blockquote><p>&quot;No volume of words will offset your actions.&quot;</p><p>— <em>Simple_Complexity</em> by William Donaldson</p></blockquote><p>Life would be easier if we could measure behaviors, not words. Doing so would reveal our actual values, how we act when things go wrong, how we act when things go our way. Daily decisions reveal our operating values, and if we don&#39;t like the optics we should change to leave a better taste in mouths. Introspection is an asset, but when we dwell only in the theoretical — the core values — we obsess over appearance and neglect what we embody in the everyday. What use is a compass if we always prefer to avoid true north because we just feel like we know a shortcut?</p><blockquote><p>&quot;Managers often try to shape or limit the feedback the employees see. This is usually a futile effort since participants in the system often see, or sense, the real feedback. Additionally, systems often hide critical feedback with delays, which mask real results and consequences.&quot;</p><p>— <em>Simple_Complexity</em> by William Donaldson</p></blockquote><p>Core values are philosophical ideals; operating values define what we stand for when things do not go to plan. Experience teaches you that being useful is preferable to being perfect. Operating values determine everything from hiring (and firing) to saying no to revenue that does not add value. Behaviors compound over time to shape the culture (good or ugly) of your firm. We plan for success by facing the truth and setting deliberate standards for our behavior up-front.</p>',6)])])}const v=o(r,[["render",i]]);export{d as __pageData,v as default};
